import{_ as m,a0 as s,w as S,s as r,I as t,x as a,a1 as n,A as l,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"回顧 Steam Machines 與 SteamOS | LCTT x X-CMD","titleTemplate":false,"description":"回顧 Steam Machines 與 SteamOS | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"回顧 Steam Machines 與 SteamOS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"回顧 Steam Machines 與 SteamOS | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20161110 User Editorial Steam Machines & SteamOS after a year in the wild","title":"回顧 Steam Machines 與 SteamOS","tag":"201710","desc":""},"relativePath":"201710/20161110 User Editorial Steam Machines & SteamOS after a year in the wild.md","filePath":"[post].md"}'),h={name:"201710/20161110 User Editorial Steam Machines & SteamOS after a year in the wild.md"};function p(d,e,M,v,V,u){const i=s("Link");return S(),r("div",null,[e[22]||(e[22]=t("h1",{id:"回顧-steam-machines-與-steamos",tabindex:"-1"},[a("回顧 Steam Machines 與 SteamOS "),t("a",{class:"header-anchor",href:"#回顧-steam-machines-與-steamos","aria-label":"Permalink to “回顧 Steam Machines 與 SteamOS”"},"​")],-1)),t("p",null,[e[1]||(e[1]=a("去年今日（LCTT 譯註：本文發表於 2016 年），在非常符合 Valve 風格的跳票之後，大眾迎來了 ",-1)),n(i,{href:"https://www.gamingonlinux.com/articles/steam-machines-steam-link-steam-controller-officially-released-steamos-sale.6201"},{default:l(()=>[...e[0]||(e[0]=[a("Steam Machines 的發佈",-1)])]),_:1}),e[2]||(e[2]=a("。即使是在 Linux 桌面環境對於遊戲的支持大步進步的今天，Steam Machines 作為一個平台依然沒有飛躍，而 SteamOS 似乎也止步不前。這些由 Valve 發起的項目究竟怎麼了？這些項目為何被髮起，又是如何失敗的？一些改進又是否曾有機會挽救這些項目的成敗？",-1))]),e[23]||(e[23]=t("h3",{id:"行業環境",tabindex:"-1"},[a("行業環境 "),t("a",{class:"header-anchor",href:"#行業環境","aria-label":"Permalink to “行業環境”"},"​")],-1)),e[24]||(e[24]=t("p",null,"在 2012 年 Windows 8 發佈的時候，微軟像 iOS 與 Android 那樣，為 Windows 集成了一個應用商店。在微軟試圖推廣對觸摸體驗友好的界面時，為了更好的提供 “Metro” UI 語言指導下的沉浸式觸摸體驗，他們同時推出了一系列叫做 “WinRT” 的 API。然而為了能夠使用這套 API，應用開發者們必須把應用程序通過 Windows 應用商城發佈，並且正如其它應用商城那樣，微軟從中抽成 30%。對於 Valve 的 CEO，Gabe Newell (G 胖) 而言，這種限制發佈平台和抽成行為是讓人無法接受的，而且他前瞻地看到了微軟利用行業龍頭地位來推廣 Windows 商店和 Metro 應用對於 Valve 潛在的危險，正如當年微軟用 IE 瀏覽器擊垮 Netscape 瀏覽器一樣。",-1)),e[25]||(e[25]=t("p",null,"對於 Valve 來説，運行 Windows 的 PC 的優勢在於任何人都可以不受操作系統和硬件方的限制運行各種軟件。當像 Windows 這樣的專有平台對像 Steam 這樣的第三方軟件限制越來越嚴格時，應用開發者們自然會想要尋找一個對任何人都更開放和自由的替代品，他們很自然的會想到 Linux 。Linux 本質上只是一套內核，但你可以輕易地使用 GNU 組件、Gnome 等軟件在這套內核上開發出一個操作系統，比如 Ubuntu 就是這麼來的。推行 Ubuntu 或者其他 Linux 發行版自然可以為 Valve 提供一個無拘無束的平台，以防止微軟或者蘋果變成 Valve 作為第三方平台之路上的的敵人，但 Linux 甚至給了 Valve 一個創造新的操作系統平台的機會。",-1)),e[26]||(e[26]=t("h3",{id:"概念化",tabindex:"-1"},[a("概念化 "),t("a",{class:"header-anchor",href:"#概念化","aria-label":"Permalink to “概念化”"},"​")],-1)),e[27]||(e[27]=t("p",null,"如果我們把 Steam Machines 叫做主機的話，Valve 當時似乎認定了主機平台是一個機會。為了迎合用户對於電視主機平台用户界面的審美期待，同時也為了讓玩家更好地從稍遠的距離上在電視上玩遊戲，Valve 為 Steam 推出了 Big Picture 模式。Steam Machines 的核心要點是開放性；比方説所有的軟件都被設計成可以脱離 Windows 工作，又比如説 Steam Machines 手柄的 CAD 圖紙也被公佈出來以便支持玩家二次創作。",-1)),e[28]||(e[28]=t("p",null,"原初計劃中，Valve 打算設計一款官方的 Steam Machine 作為旗艦機型。但最終，這些機型只在 2013 年的時候作為原型機給與了部分測試者用於測試。Valve 後來也允許像戴爾這樣的 OEM 廠商們製造 Steam Machines，並且也賦予了他們制定價格和配置規格的權利。有一家叫做 “Xi3” 的公司展示了他們設計的 Steam Machine 小型機型，那款機型小到可以放在手掌上，這一新聞創造了圍繞 Steam Machines 的更多熱烈討論。最終，Valve 決定不自己設計製造 Steam Machines，而全權交給 OEM 合作廠商們。",-1)),e[29]||(e[29]=t("p",null,"這一過程中還有很多天馬行空的創意被列入考量，比如在手柄上加入生物識別技術、眼球追蹤以及動作控制等。在這些最初的想法裏，陀螺儀被加入了 Steam Controller 手柄，HTC Vive 的手柄也有各種動作追蹤儀器；這些想法可能最初都來源於 Steam 手柄的設計過程中。手柄最初還有些更激進的設計，比如在中心放置一塊可定製化並且會隨着遊戲內容變化的觸摸屏。但最後的最後，發佈會上的手柄偏向保守了許多，但也有諸如雙觸摸板和內置軟件等黑科技。Valve 也考慮過製作面向筆記本類型硬件的 Steam Machines 和 SteamOS。這個企劃最終沒有任何成果，但也許 “Smach Z” 手持遊戲機會是發展的方向之一。",-1)),t("p",null,[e[4]||(e[4]=a("在 ",-1)),n(i,{href:"https://www.gamingonlinux.com/articles/valve-announces-steam-machines-you-can-win-one-too.2469"},{default:l(()=>[...e[3]||(e[3]=[a("2013 年九月",-1)])]),_:1}),e[5]||(e[5]=a("，Valve 對外界宣佈了 Steam Machines 和 SteamOS， 並且預告會在 2014 年中發佈。前述的 300 台原型機在當年 12 月分發給了測試者們，隨後次年 1 月，又分發給了開發者們 2000 台原型機。SteamOS 也在那段時間分發給有 Linux 經驗的測試者們試用。根據當時的測試反饋，Valve 最終決定把產品發佈延期到 2015 年 11 月。",-1))]),e[30]||(e[30]=o("",38)),t("p",null,[e[7]||(e[7]=a("本文是被一位訪客提交的，我們歡迎大家前來",-1)),n(i,{href:"https://www.gamingonlinux.com/submit-article/"},{default:l(()=>[...e[6]||(e[6]=[a("提交文章",-1)])]),_:1}),e[8]||(e[8]=a("。",-1))]),e[31]||(e[31]=t("hr",null,null,-1)),t("p",null,[e[10]||(e[10]=a("via: ",-1)),n(i,{href:"https://www.gamingonlinux.com/articles/user-editorial-steam-machines-steamos-after-a-year-in-the-wild.8474"},{default:l(()=>[...e[9]||(e[9]=[a("https://www.gamingonlinux.com/articles/user-editorial-steam-machines-steamos-after-a-year-in-the-wild.8474",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=a("作者：",-1)),n(i,{href:"https://www.gamingonlinux.com/profiles/5163"},{default:l(()=>[...e[11]||(e[11]=[a("calvin",-1)])]),_:1}),e[15]||(e[15]=a(" 譯者：",-1)),n(i,{href:"https://github.com/Moelf"},{default:l(()=>[...e[12]||(e[12]=[a("Moelf",-1)])]),_:1}),e[16]||(e[16]=a(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...e[13]||(e[13]=[a("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[17]||(e[17]=[a("LCTT",-1)])]),_:1}),e[20]||(e[20]=a(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...e[18]||(e[18]=[a("Linux中國",-1)])]),_:1}),e[21]||(e[21]=a(" 榮譽推出",-1))])])}const C=m(h,[["render",p]]);export{f as __pageData,C as default};
